+address address_stub_Relocation::get_stub_for(address call, nmethod* code) {
+  if (code->relocation_size() == 0) {
+    return nullptr;
+  }
+
+  RelocIterator iter(code, call);
+  while (iter.next()) {
+    if (iter.type() == relocInfo::address_stub_type &&
+        iter.address_stub_reloc()->owner() == call) {
+      return iter.addr();
+    }
+  }
+  return nullptr;
+}
